public record PermissionStart(
        String permissionId, String workspaceId, long workspaceGeneration,
        String riskLevel, String riskRuleId, Instant createdAt, Instant expiresAt) {
    public PermissionStart {
        requireText(permissionId, "permissionId");
        requireText(workspaceId, "workspaceId");
        if (workspaceGeneration < 0) throw new IllegalArgumentException("workspaceGeneration must be non-negative");
        requireText(riskLevel, "riskLevel");
        requireText(riskRuleId, "riskRuleId");
        Objects.requireNonNull(createdAt, "createdAt");
        Objects.requireNonNull(expiresAt, "expiresAt");
        if (!expiresAt.isAfter(createdAt)) {
            throw new IllegalArgumentException("permission expiry must follow creation");
        }
    }
}
